  "wp.message.26a6374fbf59": "ส่วนเสริม Pixflow เริ่มไม่ได้ ตรวจสอบว่าปลั๊กอิน Pixflow เข้ากันได้แล้วโหลดใหม่ ฟีเจอร์อื่นอาจยังใช้ได้",
  "wp.message.ca7714cffbcc": "เปิดใช้งาน Pro",
  "wp.message.197c83a2f752": "คืนค่าเครื่องมือพรีเมียมด้วยส่วนเสริม Pro ใบอนุญาต เนื้อหา และการตั้งค่าที่บันทึกยังคงอยู่ หากเคยใช้การยืนยันสองขั้นตอน Bricks ให้เปิดอีกครั้งในการตั้งค่าหลังเปิด Pro",
  "wp.message.2ffdcbc380ea": "สร้างด้วยตัวสร้างที่คุณชอบ เพิ่มคำอธิบายประกอบ เสียง ระบบการออกแบบ และการสร้างรูปภาพในเวิร์กโฟลว์",
  "wp.message.40ed1102964b": "ตรวจสอบการทดลอง Pro",
  "wp.message.e9cccd3ef5fc": "บันทึกการปิดไม่ได้ โปรดลองอีกครั้ง",
  "wp.message.1372089fb797": "ปิดแบนเนอร์ Pixflow Pro",
  "wp.message.5e3ba715018d": "ดาวน์โหลด Pro",
  "wp.message.fb2e6d87b44c": "เพิ่มความเป็นไปได้ด้วย Pixflow Design Pro",
  "wp.message.9934717ca744": "รีเฟรชหน้านี้แล้วลองอีกครั้ง",
  "wp.message.7c78f9990490": "เริ่มทดลอง Pro 7 วัน",
  "wp.message.f89b4dcf2c2e": "ทดลอง Pro 7 วัน",
  "wp.message.69ecce9deb2d": "คุณปิดประกาศนี้ไม่ได้",
  "wp.message.927384e7eed8": "แผน Pixflow ของคุณรวม Pro",
